/// Собрать состав хода: герой первым — к нему падают объявления без явного адресата.
///
/// Статы участников ПРОИЗВОДНЫЕ: база плюс модификаторы надетого и активных эффектов.
/// Против них бросает движок, их же показывает лист персонажа и блок состояния, поэтому
/// цифры на экране не расходятся с теми, по которым считается попадание. Первый персонаж —
/// протагонист: только он наследует бесхозные предметы, сохранённые до появления владельцев.
/// ВНИМАНИЕ: обратно в хранилище можно писать только HP/смерть/эффекты, иначе бонусы
/// запекутся в базу и начнут складываться каждый ход.
pub fn build_actors(
    characters: &[StoryCharacter],
    rpg: &[(String, CharacterRpg)],
    items: &[Item],
    enemies: &[Enemy],
) -> ActorMap {
    let mut actors = ActorMap::new();
    for (index, character) in characters.iter().enumerate() {
        let state = rpg
            .iter()
            .find(|(id, _)| id == &character.id)
            .map(|(_, state)| state.clone())
            .unwrap_or_default();
        let derived =
            du_rpg::derive_for_owner(&state, items, Some(&character.id), index == 0).rpg;
        actors.insert(character.id.clone(), Actor { name: character.name.clone(), rpg: derived });
    }
    // У врагов инвентаря нет: их статы уже окончательные.
    for enemy in enemies.iter().filter(|enemy| !enemy.rpg.dead) {
        actors.insert(enemy.id.clone(), Actor { name: enemy.name.clone(), rpg: enemy.rpg.clone() });
    }
    actors
}

