/// Эталонный клип голоса и его расшифровка, если она лежит рядом.
fn voice_reference(root: &PathBuf, voice: &str) -> Option<(PathBuf, Option<String>)> {
    let dir = root.join("models").join("voices");
    let wanted = voice.trim();
    if wanted.is_empty() {
        return None;
    }
    // Имя голоса в путь НЕ подставляем: перебираем реальные записи каталога и сравниваем
    // с ними. Выйти из каталога по-прежнему нельзя (путь берётся у read_dir, а не у игрока),
    // но пробел и кириллица в имени файла теперь работают — а именно так голоса и кладут.
    let mut found: Option<PathBuf> = None;
    let mut best = usize::MAX;
    for entry in std::fs::read_dir(&dir).ok()?.flatten() {
        let path = entry.path();
        if path.file_stem().map(|stem| stem.to_string_lossy() != wanted).unwrap_or(true) {
            continue;
        }
        let Some(extension) = path.extension().map(|e| e.to_string_lossy().to_lowercase()) else {
            continue;
        };
        // Порядок предпочтения тот же, что был: wav, затем mp3, затем flac.
        let Some(rank) = ["wav", "mp3", "flac"].iter().position(|known| *known == extension) else {
            continue;
        };
        if rank < best && path.is_file() {
            best = rank;
            found = Some(path);
        }
    }
    let clip = found?;
    let transcript = std::fs::read_to_string(clip.with_extension("txt"))
        .ok()
        .map(|text| text.trim().to_string())
        .filter(|text| !text.is_empty());
    Some((clip, transcript))
}

