/// Подготовленный эталон называется «{голос}.ref{N}s.wav» и лежит в том же каталоге. Это
/// служебный файл, а не голос: в перечень он попадать не должен.
fn is_prepared_reference(stem: &str) -> bool {
    stem.rsplit_once('.')
        .and_then(|(_, tail)| tail.strip_prefix("ref"))
        .and_then(|rest| rest.strip_suffix('s'))
        .is_some_and(|digits| !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()))
}

/// Голоса, доступные локально: по эталонным клипам в каталоге голосов. Тот же перечень
/// отдаёт `/api/voices`, поэтому раздача голосов персонажам совпадает с тем, что видит игрок.
pub fn available_voices(root: &std::path::Path) -> Vec<String> {
    let mut voices: Vec<String> = std::fs::read_dir(root.join("models").join("voices"))
        .map(|entries| {
            entries
                .flatten()
                .filter_map(|entry| {
                    let path = entry.path();
                    let extension = path.extension()?.to_string_lossy().to_lowercase();
                    ["wav", "mp3", "flac"]
                        .contains(&extension.as_str())
                        .then(|| path.file_stem().map(|stem| stem.to_string_lossy().into_owned()))?
                })
                .filter(|stem| !is_prepared_reference(stem))
                .collect()
        })
        .unwrap_or_default();
    voices.sort();
    // Один голос может лежать и в wav, и в mp3 — это ОДИН голос, а не два пункта в списке.
    voices.dedup();
    voices
}

