/// Привести эталонный клип к WAV 16 кГц моно длиной не больше `seconds`. Результат кладётся
/// рядом и переиспользуется, пока не устарел.
fn ensure_wav_reference(source: &std::path::Path, seconds: u32) -> Result<std::path::PathBuf, String> {
    let prepared = source.with_extension(format!("ref{seconds}s.wav"));
    // Готовый эталон берём, только если он НЕ старше исходника: иначе перезаписанный под тем
    // же именем голос продолжал бы звучать прежним тембром.
    let modified = |path: &std::path::Path| std::fs::metadata(path).and_then(|meta| meta.modified()).ok();
    if let (Some(ready), Some(origin)) = (modified(&prepared), modified(source)) {
        if ready >= origin {
            return Ok(prepared);
        }
    }
    // Готовим ВСЕГДА, даже когда исходник уже wav: движку нужен короткий моно-клип в его
    // частоте, а не то, что загрузил игрок.
    let outcome = std::process::Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y", "-i"])
        .arg(source)
        .args(["-t", &seconds.to_string(), "-ac", "1", "-ar", "16000"])
        .arg(&prepared)
        .status();
    match outcome {
        Ok(status) if status.success() && prepared.is_file() => Ok(prepared),
        Ok(_) => Err(format!("не удалось подготовить эталон голоса из {}", source.display())),
        // ffmpeg не поставлен: wav отдаём как раньше — тембр будет неточным, но звук будет.
        Err(error) if source.extension().map(|e| e.eq_ignore_ascii_case("wav")).unwrap_or(false) => {
            tracing::warn!("не запустить ffmpeg для эталона голоса ({error}); беру wav как есть");
            Ok(source.to_path_buf())
        }
        Err(error) => Err(format!("не запустить ffmpeg для эталона голоса: {error}")),
    }
}

