/// Имя файла клипа. ОДНО место на модуль: этим именем клип и пишется, и переигрывается.
/// В имя входит содержимое фразы и эталон — ключ между ходами повторяется (chat+номер хода,
/// messageId+номер куска), поэтому по одному ключу нельзя отдавать звук от другого текста.
fn clip_name(key: &str, index: usize, sentence: &str, reference: &std::path::Path) -> String {
    let reference_key = reference.to_string_lossy();
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in sentence.as_bytes().iter().chain(b"\0").chain(reference_key.as_bytes()) {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("tts-{}-{index}-{hash:016x}.wav", safe_name(key, 80))
}

