/// Где кончается ПОСЛЕДНЕЕ вхождение имени целым словом, если оно есть. Латиницу ограничиваем
/// границами слова, чтобы короткое имя не поймалось внутри другого; для кириллицы и прочего
/// берём вхождение — границы слова там ненадёжны.
fn mentions_name(haystack_lower: &str, name_lower: &str) -> Option<usize> {
    if name_lower.chars().count() < 2 {
        return None;
    }
    if !name_lower.is_ascii() {
        return haystack_lower.rfind(name_lower).map(|at| at + name_lower.len());
    }
    let is_word = |c: char| c.is_alphanumeric() || c == '_';
    let mut from = 0;
    let mut last = None;
    while let Some(at) = haystack_lower[from..].find(name_lower) {
        let start = from + at;
        let end = start + name_lower.len();
        let before_ok = haystack_lower[..start].chars().next_back().is_none_or(|c| !is_word(c));
        let after_ok = haystack_lower[end..].chars().next().is_none_or(|c| !is_word(c));
        if before_ok && after_ok {
            last = Some(end);
        }
        from = end;
        if from >= haystack_lower.len() {
            break;
        }
    }
    last
}

/// Кто, скорее всего, говорит: берём имя, названное БЛИЖЕ ВСЕГО к реплике — говорящего
/// объявляют прямо перед ней. При одинаковом конце вхождения выигрывает длинное имя, поэтому
/// «Капитан Мара» по-прежнему обходит «Мару». None — имени нет, читает рассказчик.
pub fn detect_speaker<'a>(
    context: &str,
    characters: &'a [StoryCharacter],
) -> Option<&'a StoryCharacter> {
    if context.trim().is_empty() {
        return None;
    }
    let haystack = context.to_lowercase();
    characters
        .iter()
        .filter(|character| !character.name.trim().is_empty())
        .filter_map(|character| {
            let name = character.name.trim().to_lowercase();
            let at = mentions_name(&haystack, &name)?;
            Some((at, name.chars().count(), character))
        })
        .max_by_key(|(at, length, _)| (*at, *length))
        .map(|(_, _, character)| character)
}

