/// Освободить карту от озвучки.
///
/// Отпустить свою ссылку мало: пока поток озвучки дочитывает фразу, он держит СВОЮ
/// копию `Arc`, и веса Higgs остаются на карте. Ждём последнего держателя — обещание
/// «к моменту возврата память свободна» иначе не выполняется.
fn release_speech(&self) {
    let mut speech = self.speech.lock().unwrap_or_else(|e| e.into_inner());
    let Some(mut engine) = speech.take() else { return };
    tracing::info!("освобождаю карту: выгружаю движок озвучки");
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
    loop {
        match Arc::try_unwrap(engine) {
            // Ссылка была последней: движок уничтожен здесь же, память вернулась.
            Ok(owned) => {
                drop(owned);
                return;
            }
            Err(shared) => {
                if std::time::Instant::now() >= deadline {
                    tracing::warn!(
                        "озвучка не отпустила карту за минуту — рисую на том, что осталось"
                    );
                    return;
                }
                engine = shared;
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
        }
    }
}

