        // Отставший подписчик теряет часть прозы, но НЕ весь ход: читаем дальше,
        // иначе поток закроется без done/error и экран замрёт навсегда, хотя ход
        // на сервере уже сохранён. Полный текст всё равно придёт в done.
        Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
    };
    let is_terminal =
        matches!(event.get("type").and_then(Value::as_str), Some("done") | Some("error"));
    if let Some(named) = to_named(&event) {
        yield Ok(named);
    }
    if is_terminal {
        break;
    }
}

