/// Записать задачу и отдать её воркеру.
///
/// Порядок обязателен: воркер молча выбрасывает задачу, которой нет в карте
/// (`None => continue`), поэтому сначала запись, и только потом отправка. Правило
/// живёт здесь ОДИН раз — постановщики выше его не повторяют.
async fn spawn(
    &self,
    body: JobFn,
    result_sender: Option<oneshot::Sender<Result<Value, String>>>,
) -> String {
    let (events, _) = broadcast::channel(256);
    let id = new_job_id();
    let job = Job {
        events,
        status: JobStatus::Queued,
        result: None,
        error: None,
        abandoned: false,
        result_sender,
    };
    self.jobs.lock().await.insert(id.clone(), job);
    let _ = self.submit.send((id.clone(), body));
    id
}

/// Поставить задачу в очередь и вернуть её идентификатор.
pub async fn enqueue(&self, body: JobFn) -> String {
    self.spawn(body, None).await
}

/// Поставить задачу и получить канал результата — когда ответ нужен прямо в этом запросе.
pub async fn enqueue_awaitable(
    &self,
    body: JobFn,
) -> (String, oneshot::Receiver<Result<Value, String>>) {
    let (sender, receiver) = oneshot::channel();
    (self.spawn(body, Some(sender)).await, receiver)
}

