    /// «отсутствующие».
    fn from_manifest(root: &Path, id: &str) -> PathBuf {
        crate::setup::manifest()
            .iter()
            .find(|component| component.id == id)
            .map(|component| root.join(component.path))
            // Идентификатор из манифеста исчез: путь заведомо не существует, и модель
            // честно объявится отсутствующей вместо тихой подстановки чужого файла.
