pub async fn runtime_put(
    State(state): State<AppState>,
    Json(body): Json<Value>,
) -> ApiResult<Json<Value>> {
    // Интерфейс шлёт ОДНО поле за раз, поэтому запрос — заплатка поверх сохранённого, а не
    // полная замена. `Runtime` помечен `#[serde(default)]`, и разбор частичного тела прямо в
    // структуру подставлял бы значения по умолчанию во все прочие поля: один щелчок тумблера
    // стирал бы выбранные модели, контекст рассказчика и настройки карты.
    let current = crate::runtime::load(&state.root);
    let mut merged = serde_json::to_value(&current).unwrap_or_else(|_| json!({}));
    let (Some(target), Some(patch)) = (merged.as_object_mut(), body.as_object()) else {
        return Err(ApiError::bad_request("настройки движков ждут объект"));
    };
    for (key, value) in patch {
        // Пустой ключ означает «не менять»: интерфейс его не получает и вернуть не может.
        if key == "openrouterKey" && value.as_str().unwrap_or_default().trim().is_empty() {
            continue;
        }
        target.insert(key.clone(), value.clone());
    }
    let next: crate::runtime::Runtime =
        serde_json::from_value(merged).map_err(|error| ApiError::bad_request(error.to_string()))?;
    let mut next = crate::runtime::sanitize(next);
    crate::runtime::save(&state.root, &next).map_err(ApiError::internal)?;
    let has_key = !next.openrouter_key.trim().is_empty();
    next.openrouter_key = String::new();
    Ok(Json(json!({ "runtime": next, "openrouterKeySet": has_key })))
}

