pub fn read_png(path: &std::path::Path) -> Result<RawImage, String> {
    let file = std::fs::File::open(path).map_err(|e| e.to_string())?;
    let mut decoder = png::Decoder::new(std::io::BufReader::new(file));
    // Игрок прикладывает какой угодно PNG. Без нормализации шестнадцатибитный кадр приезжает
    // вдвое длиннее, чем обещают ширина, высота и три канала, и движок читает как референс
