/// Разобрать JSON-колонку, пережив формат прошлых версий.
///
/// Строгий разбор ломается на ЛЮБОМ значении, которого нет в текущих перечислениях
/// (`imageBackend: "sdnq-hs"`, `textProvider: "openrouter"` из версии на better-sqlite3),
/// и тогда в умолчания схлопнулся бы ВЕСЬ объект — вместе с миром, стилем, промптами,
/// языком и голосом. Поэтому объект, не разобравшийся целиком, разбираем по частям:
/// выбрасываем поля, на которых разбор спотыкается, пока не останется читаемый остаток.
/// Умолчание достаётся тогда только испорченному полю, а не всей строке сохранения.
fn parse_or_default<T: serde::de::DeserializeOwned + Default>(raw: Option<String>) -> T {
    let Some(text) = raw.filter(|text| !text.trim().is_empty()) else {
        return T::default();
    };
    if let Ok(value) = serde_json::from_str::<T>(&text) {
        return value;
    }
    // Не объект (массив, мусор) спасать нечем — как и раньше, отдаём умолчание.
    let Ok(serde_json::Value::Object(mut map)) = serde_json::from_str::<serde_json::Value>(&text)
    else {
        return T::default();
    };
    while !map.is_empty() {
        let keys: Vec<String> = map.keys().cloned().collect();
        // Сначала ищем ОДНО поле, снятие которого чинит разбор: так теряется минимум.
        let culprit = keys.iter().find(|key| {
            let mut trial = map.clone();
            trial.remove(key.as_str());
            serde_json::from_value::<T>(serde_json::Value::Object(trial)).is_ok()
        });
        let key = culprit.cloned().unwrap_or_else(|| keys[0].clone());
        map.remove(&key);
        if let Ok(value) = serde_json::from_value::<T>(serde_json::Value::Object(map.clone())) {
            return value;
        }
    }
    T::default()
}

