/// Удалить сообщение и, при `include_after`, всё, что было после него в этом чате.
/// Именно на этом держатся «Повторить» и «Стереть»: ход убирается ЦЕЛИКОМ — вместе с
/// тем, что он успел записать в состояние игры, иначе повтор применит последствия
/// второй раз. Всё делается одной транзакцией: полуоткат хуже, чем его отсутствие.
pub fn delete_message_and_after(&self, message_id: &str, include_after: bool) -> DbResult<bool> {
    let mut conn = self.lock();
    let found = conn
        .query_row(
            "SELECT chat_id, created_at, rowid FROM messages WHERE id = ?",
            params![message_id],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, i64>(2)?)),
        )
        .optional()?;
    let Some((chat_id, created_at, rowid)) = found else { return Ok(false) };

    // Порядок тот же, что и при чтении: сначала по времени, при равенстве — по rowid.
    // Само сообщение попадает в выборку всегда, хвост — только при `include_after`,
    // поэтому обоим случаям хватает одного условия и одного набора параметров.
    const DOOMED: &str = "chat_id = ?1 AND (id = ?4
         OR (?5 AND (created_at > ?2 OR (created_at = ?2 AND rowid >= ?3))))";
    let now = now_iso();
    let tx = conn.transaction()?;

    let mut snapshots: Vec<du_rpg::RpgSnapshot> = Vec::new();
    {
        let mut stmt = tx.prepare(&format!(
            "SELECT rpg_snapshot_json FROM messages WHERE {DOOMED}
              ORDER BY created_at ASC, rowid ASC"
        ))?;
        let rows = stmt.query_map(
            params![chat_id, created_at, rowid, message_id, include_after],
            |row| row.get::<_, Option<String>>(0),
        )?;
        for raw in rows {
            if let Some(snapshot) = parse_opt::<du_rpg::RpgSnapshot>(raw?) {
                snapshots.push(snapshot);
            }
        }
    }

    // Откат от САМОГО РАННЕГО снесённого хода: базовые статы и состав стычки
    // возвращаются к состоянию ДО него, а лут и записи журнала, порождённые этими
    // ходами, удаляются — иначе повтор выдаст их второй раз.
    if let Some(base) = snapshots.first() {
        for (character_id, rpg) in &base.chars {
            tx.execute(
                "UPDATE characters SET rpg_json = ?, updated_at = ? WHERE id = ? AND chat_id = ?",
                params![
                    serde_json::to_string(rpg).unwrap_or_else(|_| "{}".into()),
                    now,
                    character_id,
                    chat_id
                ],
            )?;
        }
        tx.execute(
            "UPDATE chats SET combatants_json = ? WHERE id = ?",
            params![
                serde_json::to_string(&base.combatants).unwrap_or_else(|_| "[]".into()),
                chat_id
            ],
        )?;
        for snapshot in &snapshots {
            for id in &snapshot.item_ids {
                tx.execute(
                    "DELETE FROM items WHERE id = ? AND chat_id = ?",
                    params![id, chat_id],
                )?;
            }
            for id in &snapshot.event_ids {
                tx.execute(
                    "DELETE FROM events WHERE id = ? AND chat_id = ?",
                    params![id, chat_id],
                )?;
            }
        }
    }

    tx.execute(
        &format!("DELETE FROM messages WHERE {DOOMED}"),
        params![chat_id, created_at, rowid, message_id, include_after],
    )?;
    tx.execute("UPDATE chats SET updated_at = ? WHERE id = ?", params![now, chat_id])?;
    tx.commit()?;
    Ok(true)
}

