/// Надеть или снять предмет. Надевание СНИМАЕТ то, что занимало тот же слот у того
/// же владельца, — правило «один предмет на слот» держится и здесь, и в выводе статов.
///
/// Чтение соседей и все записи идут ОДНОЙ транзакцией под одним захватом мьютекса:
/// иначе два одновременных запроса видят одинаковое «до» и оба остаются надетыми.
/// Помощники `get_item`/`list_items`/`put_item` здесь звать нельзя — мьютекс не
/// реентрантный, вложенный захват повесит сервер, — поэтому запросы записаны прямо.
pub fn set_item_equipped(&self, chat_id: &str, item_id: &str, equipped: bool) -> DbResult<Option<Item>> {
    let mut conn = self.lock();
    let tx = conn.transaction()?;
    let raw: Option<String> = tx
        .query_row(
            "SELECT data_json FROM items WHERE id = ? AND chat_id = ?",
            params![item_id, chat_id],
            |row| row.get(0),
        )
        .optional()?;
    let Some(mut item) = raw.and_then(|raw| serde_json::from_str::<Item>(&raw).ok()) else {
        return Ok(None);
    };
    if equipped {
        let siblings: Vec<(String, String)> = {
            let mut stmt = tx.prepare("SELECT id, data_json FROM items WHERE chat_id = ?")?;
            let rows = stmt.query_map(params![chat_id], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })?;
            rows.collect::<Result<_, _>>()?
        };
        for (id, raw) in siblings {
            if id == item.id {
                continue;
            }
            let Ok(mut other) = serde_json::from_str::<Item>(&raw) else { continue };
            if !other.equipped || other.slot != item.slot || other.owner_id != item.owner_id {
                continue;
            }
            other.equipped = false;
            tx.execute(
                "UPDATE items SET data_json = ? WHERE id = ? AND chat_id = ?",
                params![
                    serde_json::to_string(&other).unwrap_or_else(|_| "{}".into()),
                    id,
                    chat_id
                ],
            )?;
        }
    }
    item.equipped = equipped;
    tx.execute(
        "UPDATE items SET data_json = ? WHERE id = ? AND chat_id = ?",
        params![
            serde_json::to_string(&item).unwrap_or_else(|_| "{}".into()),
            item.id,
            chat_id
        ],
    )?;
    tx.execute("UPDATE chats SET updated_at = ? WHERE id = ?", params![now_iso(), chat_id])?;
    tx.commit()?;
    Ok(Some(item))
}

