fn strip_closed_fences(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(open) = rest.find("```") {
        let after_open = &rest[open + 3..];
        // Ограда считается настоящей, только если между ``` и переводом строки стоит
        // ярлык языка (или ничего) И блок закрыт второй оградой.
        let closed = after_open
            .find('\n')
            .filter(|newline| after_open[..*newline].chars().all(|c| c.is_ascii_alphanumeric()))
            .and_then(|newline| {
                let body = &after_open[newline + 1..];
                body.find("```").map(|close| &body[close + 3..])
            });
        match closed {
            // Закрытый блок вырезаем целиком вместе с телом.
            Some(tail) => {
                out.push_str(&rest[..open]);
                rest = tail;
            }
            // Случайные кавычки в прозе или незакрытый блок: раньше здесь стоял break, и
            // один такой прогон отменял чистку ВСЕХ блоков ниже по тексту. Оставляем эти
            // кавычки как есть и продолжаем искать ограды дальше.
            None => {
                out.push_str(&rest[..open + 3]);
                rest = after_open;
            }
        }
    }
    out.push_str(rest);
    out
}

