pub fn finalize_scene_prompt(prompt: &str, style_prefix: &str) -> String {
    const NO_TEXT: &str = "No text, no letters, no words, no captions, no watermark, no UI.";
    let styled = apply_style_prefix(prompt, style_prefix);
    let styled = styled.trim_end();
    if styled.to_lowercase().contains("no text, no letters") {
        return styled.to_string();
    }
    // Если промпт уже кончается знаком препинания, второй не нужен.
    let separator = if styled.ends_with(['.', '!', '?', ',', ':', ';']) { " " } else { ". " };
    format!("{styled}{separator}{NO_TEXT}")
}

