extern "C" fn progress_trampoline(step: c_int, steps: c_int, time: f32, _data: *mut c_void) {
    if let Ok(guard) = PROGRESS.lock() {
        if let Some(sink) = guard.as_ref() {
            // Паника чужого замыкания не имеет права уйти обратно в C: у `extern "C"` это
            // немедленное завершение процесса, то есть потеря всех сессий из-за одного кадра.
            // Ловим её здесь же, не выпуская наружу и не отравляя мьютекс.
            let called = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                sink(step, steps, time);
            }));
            if called.is_err() {
                tracing::error!(target: "sd", "колбэк прогресса запаниковал на шаге {step}, прогресс дальше не шлём");
            }
        }
    }
}

