        let clip = &audio[a..b];
        let mut ws = self.transcribe_words(clip, sr)?;
        let off = w.offset();
        for word in &mut ws {
            word.start += off;
            word.end += off;
        }
        append_dedup_words(&mut all, ws, w.start);
    }
    Ok(all)
}

/// Окно -> полу-открытый диапазон сэмплов [a, b) в буфере длины `len`; None, если окно пустое или
/// целиком за концом буфера. Одно правило на оба пути (последовательный и параллельный) — раньше
/// эта арифметика была записана дважды и расходилась бы при первой же правке границ.
fn clip_range(w: &window::Window, sr: u32, len: usize) -> Option<(usize, usize)> {
    let a = ((w.start * sr as f64) as usize).min(len);
    let b = ((w.end * sr as f64) as usize).min(len);
    if b <= a {
        None
    } else {
        Some((a, b))
    }
}

/// Параллельный оконный прогон: пул из `workers` потоков, КАЖДЫЙ со своей сессией
/// `ParakeetTDT::from_pretrained` (эксклюзивность `&mut self` обходится числом сессий, не очередью).
/// Очередь окон общая; результаты собираются по индексу окна и склеиваются В ПОРЯДКЕ окон тем же
/// `append_dedup_words`, что и последовательный путь (та же обработка overlap-швов).
fn windowed_parallel(
    &mut self,
    audio: &[f32],
    sr: u32,
    windows: &[window::Window],
    workers: usize,
) -> Result<Vec<Word>, AsrError> {
    ensure_ort_dylib();
    // Задания: (индекс окна, offset, w.start, клип-копия O(окна)).
    let jobs: Vec<(usize, f64, f64, Vec<f32>)> = windows
        .iter()
        .enumerate()
        .filter_map(|(i, w)| {
            let (a, b) = Self::clip_range(w, sr, audio.len())?;
            Some((i, w.offset(), w.start, audio[a..b].to_vec()))
        })
        .collect();

