    clipQueueRef.current = Promise.resolve();
  }
  clipQueueRef.current = clipQueueRef.current
    .then(() => {
      // Пока клип стоял в очереди, озвучку могли прервать — тогда он не звучит.
      if (speakSeqRef.current !== seq) return;
