// Сервер принимает НЕ заплатку, а весь Runtime целиком: пропущенные поля serde добивает
// значениями по умолчанию (crates/du-server/src/runtime.rs, `#[serde(default)]` над
// структурой). Поэтому отправляем последний известный слепок, а изменённое кладём
// сверху. Ключ уходит пустым — на сервере это ровно «оставить как есть».
const save = useCallback(
  async (patch: Partial<Runtime>): Promise<boolean> => {
    setSaving(true);
    setNote("");
    try {
      const response = await fetch("/api/runtime", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...(runtime ?? {}), ...patch }),
      });
      if (!response.ok) throw new Error(await response.text());
      // Ответ на PUT — это уже сохранённые (и зажатые сервером) настройки. Второй запрос
      // за тем же самым не нужен: он только добавлял лишний круг и гонку ответов.
      const data = await response.json();
      setRuntime(data.runtime);
      setKeySet(Boolean(data.openrouterKeySet));
      // Перезапуск не нужен: сервер перечитывает настройки на каждом запуске модели.
      setNote("Сохранено — действует со следующего хода.");
      return true;
    } catch (error) {
      setNote(`Не сохранилось: ${error instanceof Error ? error.message : String(error)}`);
      // Переключатель мы двигаем сразу, не дожидаясь ответа. Раз ответа нет — возвращаем
      // то, что на сервере: иначе панель показывала бы облако там, где его не включили.
      try {
        const data = await (await fetch("/api/runtime")).json();
        setRuntime(data.runtime);
        setKeySet(Boolean(data.openrouterKeySet));
      } catch {
        // связи нет вовсе — оставляем как есть, сообщение об ошибке уже показано
      }
      return false;
    } finally {
      setSaving(false);
    }
  },
  [runtime],
);

