// Какие назначения уже запрошены. Держим отдельно от `models`, потому что отметка нужна
// РАНЬШЕ ответа: пока запрос в пути, в `models` ничего нет, и эффект (он зависел от
// `models`) отправлял тот же запрос заново на каждый чужой ответ. useState с ленивым
// инициализатором даёт стабильный объект на всё время жизни панели.
const [requested] = useState(() => new Set<string>());
// Списки моделей тянем только когда панель открыта: это сетевой запрос к провайдеру.
useEffect(() => {
  if (!open || !keySet) return;
  for (const stage of STAGES) {
    if (requested.has(stage.kind)) continue;
    requested.add(stage.kind);
    void (async () => {
      try {
        const response = await fetch(`/api/cloud/models?kind=${stage.kind}`);
        // Провайдер отвечает и ошибкой в формате JSON, поэтому статус проверяем сами:
        // иначе `.map` падал бы на теле ошибки и провал выглядел бы как пустой список.
        if (!response.ok) throw new Error(await response.text());
        const data = await response.json();
        const list: string[] = (data.models ?? data).map((m: { id: string }) => m.id).sort();
        setModels((current) => ({ ...current, [stage.kind]: list }));
      } catch {
        // Отметку снимаем: провал запоминать нельзя, иначе выпадающий список молча
        // останется пустым до перезагрузки страницы. Следующее открытие панели
        // попробует снова, а игроку говорим, что списка нет и почему.
        requested.delete(stage.kind);
        setModels((current) => ({ ...current, [stage.kind]: [] }));
        setNote("Список облачных моделей не пришёл — открой панель ещё раз.");
      }
    })();
  }
}, [open, keySet, requested]);

