// The full ordered stream the book paginates: the narrator's passages, the
// player's own actions, and each turn's resolved game events — one interleaved
// adventure, not just the narration.
const streamNow = useMemo(
  () => messages.filter((message) => message.content.trim() || message.events?.length),
  [messages],
);
// Упаковка страниц меряет в DOM КАЖДЫЙ абзац книги, а во время хода рассказчика текст
// приходит потоком и messages меняется десятки раз в секунду. Поэтому наружу поток
// отдаём через тормоз — не чаще раза в 200 мс. Иначе каждый кусочек текста стоит
// полной переверстки всей книги и пересоздания флипбука, и читать становится нечего:
// страница только дёргается. Последний кусочек не теряется — на него приходит
// последний тик тормоза.
const [stream, setStream] = useState(streamNow);
const packedAt = useRef(0);
useEffect(() => {
  const id = window.setTimeout(
    () => {
      packedAt.current = Date.now();
      setStream(streamNow);
    },
    Math.max(0, 200 - (Date.now() - packedAt.current)),
  );
  return () => window.clearTimeout(id);
}, [streamNow]);

