    let transcript = packed.evicted[covered..]
        .iter()
        .map(|message| {
            let who = match message.role {
                StoryRole::User => "Игрок",
                StoryRole::Assistant => "Рассказчик",
            };
            format!("{who}: {}", message.content)
        })
        .collect::<Vec<_>>()
        .join("\n\n");
    let ask = vec![
